1	//! Which files in an IDE config directory are worth syncing.
2	//!
3	//! The allowlist is *learned* rather than hard-coded.
4	//!
5	//! Any IDE that has run JetBrains' bundled Backup and Sync leaves a
6	//! `settingsSync/` working tree, and that tree is the platform's own answer to
7	//! "what roams" — it is produced by the same `RoamingType` annotations the
8	//! platform uses internally. Pooling those trees across every installed IDE
9	//! gives an authoritative list for free, including for IDEs that never enabled
10	//! Backup and Sync.
11	//!
12	//! This matters more than it sounds. Guessing `options/*.xml` sweeps up files
13	//! JetBrains deliberately does not roam: `other.xml` is per-machine UI state,
14	//! and the `llm.*.xml` files hold opaque JSON blobs that cannot be merged
15	//! meaningfully. A hand-maintained list would drift; a learned one does not.
16	//!
17	//! Only when no IDE has such a tree does `BUILTIN_MANIFEST` step in. Either
18	//! way the result is filtered by the exclusion list, which removes caches,
19	//! telemetry, machine-local state, and credentials.
20	
21	use std::{
22	    collections::BTreeMap,
23	    path::{Path, PathBuf},
24	};
25	
26	use globset::{Glob, GlobSetBuilder};
27	
28	use crate::{
29	    config::SyncConfig,
30	    error::{JbsyncError, Result},
31	    ide::Ide,
32	};
33	
34	/// JetBrains records a removed setting by writing this literal into the
35	/// `settingsSync` tree instead of deleting the file.
36	pub const DELETED_TOMBSTONE: &str = "DELETED";
37	
38	/// Fallback allowlist, used only when no installed IDE has a `settingsSync`
39	/// tree to learn from.
40	///
41	/// This mirrors what the platform actually roams. It is deliberately *not*
42	/// `options/*.xml`: JetBrains excludes plenty of files in that directory —
43	/// `other.xml` holds per-machine UI state, `llm.*.xml` holds opaque JSON blobs
44	/// — and syncing them produces noise and unresolvable conflicts.
45	///
46	/// Every entry here has been checked against real `settingsSync` trees: a file
47	/// that exists in an IDE's `options/` but never appears in that IDE's
48	/// `settingsSync/` is one the platform declines to roam, and does not belong
49	/// here. `project.default.xml` (nested per-project components and a JSON blob
50	/// of machine-local paths), `find.xml` (search history), `advancedSettings.xml`,
51	/// `console-font.xml`, `terminal-font.xml` and `textmate.xml` all failed that
52	/// check across four products and were removed.
53	const BUILTIN_MANIFEST: &[&str] = &[
54	    "codestyles/**",
55	    "colors/**",
56	    "fileTemplates/**",
57	    "filetypes/**",
58	    "inspection/**",
59	    "keymaps/**",
60	    "quicklists/**",
61	    "templates/**",
62	    "options/colors.scheme.xml",
63	    "options/csvSettings.xml",
64	    "options/customization.xml",
65	    "options/databaseDrivers.xml",
66	    "options/databaseSettings.xml",
67	    "options/dataViewsSettings.xml",
68	    "options/debugger.xml",
69	    "options/diff.xml",
70	    "options/editor-font.xml",
71	    "options/editor.xml",
72	    "options/file.template.settings.xml",
73	    "options/filetypes.xml",
74	    "options/github.xml",
75	    "options/gitlab.xml",
76	    "options/grazie_global.xml",
77	    "options/ide-features-trainer.xml",
78	    "options/ide.general.xml",
79	    "options/IntelliLang.xml",
80	    "options/laf.xml",
81	    "options/sshConfigs.xml",
82	    "options/terminal.xml",
83	    "options/ui.lnf.xml",
84	    "options/vcs.xml",
85	];
86	
87	/// Never sync these. Caches and indices, machine-local layout, credentials,
88	/// telemetry, and one-shot promotional/onboarding state.
89	const EXCLUDES: &[&str] = &[
90	    "**/.DS_Store",
91	    ".DS_Store",
92	    "*.db",
93	    "*.db-*",
94	    "app-internal-state.db*",
95	    "bundled_plugins.txt",
96	    "disabled_plugins.txt",
97	    "early-access-registry.txt",
98	    "event-log-metadata/**",
99	    "extensions/**",
100	    "grazie/**",
101	    "idea.key",
102	    "log/**",
103	    "plugins/**",
104	    "splash-subscription-mode.txt",
105	    "ssl/**",
106	    "system/**",
107	    "tasks/**",
108	    "updatedBrokenPlugins.db",
109	    "workspace/**",
110	    // The bundled sync's own state. Syncing it would make the two tools fight.
111	    "settingsSync/**",
112	    "options/settingsSync.xml",
113	    "options/settingsSyncLocal.xml",
114	    // Machine-local: window geometry, recent paths, per-host trust.
115	    "options/ide.general.local.xml",
116	    "options/path.macros.xml",
117	    "options/proxy.settings.xml",
118	    "options/recentProjects.xml",
119	    "options/sshRecentConnections*.xml",
120	    "options/trusted-paths.xml",
121	    "options/updates.xml",
122	    "options/window.layouts.xml",
123	    "options/window.state.xml",
124	    // Telemetry and usage counters.
125	    "options/actionSummary.xml",
126	    "options/EventLogAllowedList.xml",
127	    "options/features.usage.statistics.xml",
128	    "options/usage.statistics.xml",
129	    // Licensing and quota, which is per-account and not portable.
130	    "options/AIAssistantQuotaManager2.xml",
131	    "options/trace_license_storage.xml",
132	    // One-shot onboarding and promotion flags.
133	    "options/AIChatContextPopupPromotionState.xml",
134	    "options/AIOnboardingPromoWindowAdvisor.xml",
135	    "options/DefaultAgentRollout.xml",
136	    "options/embeddings-activation.xml",
137	    "options/InstallJunieHubActionManager.xml",
138	    "options/ml.chat.completion.survey.xml",
139	    "options/llm.cloud.completion.xml",
140	];
