142	fn glob_set(patterns: &[String]) -> Result<globset::GlobSet> {
143	    let mut builder = GlobSetBuilder::new();
144	    for pattern in patterns {
145	        builder.add(Glob::new(pattern).map_err(|error| {
146	            JbsyncError::configuration(format!("invalid pattern {pattern:?}: {error}"))
147	        })?);
148	    }
149	    builder
150	        .build()
151	        .map_err(|error| JbsyncError::configuration(error.to_string()))
152	}
