154	/// The name this IDE uses for its VM options file (`idea.vmoptions`,
155	/// `pycharm.vmoptions`, ...), so it can be stored under one shared name.
156	pub fn vm_options_name(ide: &Ide, config: &SyncConfig) -> String {
157	    if let Some(name) = config.jetbrains.vmoptions_names.get(&ide.product) {
158	        return name.clone();
159	    }
160	    if let Some(metadata) = &ide.metadata
161	        && !metadata.vm_options_file.is_empty()
162	    {
163	        return metadata.vm_options_file.clone();
164	    }
165	    "idea.vmoptions".to_string()
166	}
167	
168	/// Maps a product-specific path onto the name used inside the store, so every
169	/// IDE shares one `idea.vmoptions`.
170	pub fn canonical_relative_path(relative: &str, ide: &Ide, config: &SyncConfig) -> String {
171	    if relative == vm_options_name(ide, config) {
172	        "idea.vmoptions".to_string()
173	    } else {
174	        relative.to_string()
175	    }
176	}
177	
178	/// The reverse of [`canonical_relative_path`]: where a stored file belongs
179	/// inside a particular IDE.
180	pub fn target_relative_path(relative: &str, ide: &Ide, config: &SyncConfig) -> String {
181	    if relative == "idea.vmoptions" {
182	        vm_options_name(ide, config)
183	    } else {
184	        relative.to_string()
185	    }
186	}
187	
188	pub fn is_tombstone(contents: &str) -> bool {
189	    contents.trim() == DELETED_TOMBSTONE
190	}
191	
192	/// Relative paths the IDE's own bundled sync considers roamable.
193	fn settings_sync_manifest(ide: &Ide) -> Vec<String> {
194	    let root = ide.path.join("settingsSync");
195	    let mut found = Vec::new();
196	    let mut stack = vec![root.clone()];
197	    while let Some(directory) = stack.pop() {
198	        let Ok(entries) = std::fs::read_dir(&directory) else {
199	            continue;
200	        };
201	        for entry in entries.flatten() {
202	            let path = entry.path();
203	            let Ok(metadata) = entry.metadata() else {
204	                continue;
205	            };
206	            if metadata.is_symlink() {
207	                continue;
208	            }
209	            if metadata.is_dir() {
210	                // `.git` is the bundled sync's own history, not settings.
211	                if path.file_name().is_some_and(|name| name == ".git") {
212	                    continue;
213	                }
214	                stack.push(path);
215	                continue;
216	            }
217	            let Ok(relative) = path.strip_prefix(&root) else {
218	                continue;
219	            };
220	            let relative = to_slash(relative);
221	            // Anything dot-prefixed here belongs to the bundled sync's own
222	            // bookkeeping (`.metainfo/`, `.gitignore`) or to the operating
223	            // system (`.DS_Store`) — never to a setting. Filtering by the
224	            // convention rather than by name keeps the published manifest clean
225	            // as JetBrains adds more of them.
226	            if relative.split('/').any(|part| part.starts_with('.')) {
227	                continue;
228	            }
229	            // A tombstone records a deletion; the live file, if any, is stale.
230	            if std::fs::read_to_string(&path).is_ok_and(|contents| is_tombstone(&contents)) {
231	                continue;
232	            }
233	            found.push(relative);
234	        }
235	    }
236	    found
237	}
238	
239	fn to_slash(path: &Path) -> String {
240	    path.components()
241	        .map(|component| component.as_os_str().to_string_lossy())
242	        .collect::<Vec<_>>()
243	        .join("/")
244	}
