246	/// The allowlist to apply to every IDE on this machine.
247	///
248	/// Any IDE that has run JetBrains' bundled Backup and Sync carries an
249	/// authoritative list of what the platform roams, produced by the same
250	/// `RoamingType` annotations the IDE uses internally. Pooling those lists means
251	/// an IDE that never enabled Backup and Sync — or a freshly installed one —
252	/// still syncs exactly the right files, learned from its siblings rather than
253	/// from a list this project would have to maintain by hand.
254	/// `remembered` is the union every machine has contributed so far, replicated
255	/// through the store. Including it means a machine where Backup and Sync was
256	/// never enabled — a fresh laptop, or a product like WebStorm that ships
257	/// without the tree its siblings have — inherits everything the fleet has
258	/// learned, instead of dropping to the built-in list.
259	pub fn learned_manifest(ides: &[&Ide], remembered: &[String]) -> Vec<String> {
260	    observed_manifest(ides)
261	        .into_iter()
262	        .chain(remembered.iter().cloned())
263	        // The built-in list is a floor, not a last resort. Unioning it always
264	        // means one IDE with a thin `settingsSync` tree cannot narrow what the
265	        // rest of them sync.
266	        .chain(BUILTIN_MANIFEST.iter().map(|value| (*value).to_string()))
267	        .collect::<std::collections::BTreeSet<String>>()
268	        .into_iter()
269	        .collect()
270	}
271	
272	/// Only what the installed IDEs can prove right now, with nothing remembered or
273	/// built-in folded in. This is what gets published back to the store, so the
274	/// record stays evidence the platform itself produced.
275	pub fn observed_manifest(ides: &[&Ide]) -> Vec<String> {
276	    let mut pooled: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
277	    for ide in ides {
278	        pooled.extend(settings_sync_manifest(ide));
279	    }
280	    pooled.into_iter().collect()
281	}
282	
283	/// Every file this IDE should contribute, keyed by its path inside the store.
284	///
285	/// `manifest` comes from [`learned_manifest`]; passing an empty slice falls
286	/// back to the built-in list.
287	pub fn discover(
288	    ide: &Ide,
289	    config: &SyncConfig,
290	    manifest: &[String],
291	) -> Result<BTreeMap<String, PathBuf>> {
292	    let excludes = {
293	        let mut patterns: Vec<String> = if config.jetbrains.use_default_excludes {
294	            EXCLUDES.iter().map(|value| (*value).to_string()).collect()
295	        } else {
296	            Vec::new()
297	        };
298	        patterns.extend(config.jetbrains.exclude.clone());
299	        glob_set(&patterns)?
300	    };
301	    let explicit = glob_set(&config.jetbrains.explicit_include)?;
302	
303	    let mut patterns: Vec<String> = if manifest.is_empty() {
304	        BUILTIN_MANIFEST
305	            .iter()
306	            .map(|value| (*value).to_string())
307	            .collect()
308	    } else {
309	        manifest.to_vec()
310	    };
311	    patterns.extend(config.jetbrains.include.clone().unwrap_or_default());
312	    let manifest = glob_set(&patterns)?;
313	
314	    let mut candidates: Vec<String> = walk_relative(&ide.path);
315	    candidates.sort_unstable();
316	    candidates.dedup();
317	
318	    let mut selected = BTreeMap::new();
319	    for relative in candidates {
320	        let absolute = ide.path.join(&relative);
321	        if !absolute.is_file() {
322	            continue;
323	        }
324	        let explicitly_included = explicit.is_match(&relative);
325	        if !explicitly_included && (excludes.is_match(&relative) || !manifest.is_match(&relative)) {
326	            continue;
327	        }
328	        selected.insert(canonical_relative_path(&relative, ide, config), absolute);
329	    }
330	    Ok(selected)
331	}
332	
333	/// Top-level files plus the directories the manifest can match, without
334	/// descending into caches. Keeps discovery cheap on large config directories.
335	fn walk_relative(root: &Path) -> Vec<String> {
336	    const SKIP: [&str; 8] = [
337	        "plugins",
338	        "workspace",
339	        "system",
340	        "log",
341	        "event-log-metadata",
342	        "settingsSync",
343	        "tasks",
344	        "extensions",
345	    ];
346	    let mut found = Vec::new();
347	    let mut stack = vec![root.to_path_buf()];
348	    while let Some(directory) = stack.pop() {
349	        let Ok(entries) = std::fs::read_dir(&directory) else {
350	            continue;
351	        };
352	        for entry in entries.flatten() {
353	            let path = entry.path();
354	            let Ok(metadata) = entry.metadata() else {
355	                continue;
356	            };
357	            if metadata.is_symlink() {
358	                continue;
359	            }
360	            if metadata.is_dir() {
361	                let name = path.file_name().unwrap_or_default().to_string_lossy();
362	                if !SKIP.contains(&name.as_ref()) {
363	                    stack.push(path);
364	                }
365	            } else if let Ok(relative) = path.strip_prefix(root) {
366	                found.push(to_slash(relative));
367	            }
368	        }
369	    }
370	    found
371	}
