374	mod tests {
375	    use super::*;
376	    use crate::ide::{Ide, ProductMetadata};
377	
378	    fn ide_at(path: &Path, product: &str, vm_options: &str) -> Ide {
379	        Ide {
380	            product: product.to_string(),
381	            path: path.to_path_buf(),
382	            pattern_index: 0,
383	            metadata: Some(ProductMetadata {
384	                vm_options_file: vm_options.to_string(),
385	                ..ProductMetadata::default()
386	            }),
387	        }
388	    }
