390	    #[test]
391	    fn detects_tombstones() {
392	        assert!(is_tombstone("DELETED"));
393	        assert!(is_tombstone("DELETED\n"));
394	        assert!(!is_tombstone("<application />"));
395	    }
396	
397	    #[test]
398	    fn vm_options_are_stored_under_one_shared_name() {
399	        let directory = tempfile::tempdir().unwrap();
400	        let ide = ide_at(directory.path(), "PyCharm", "pycharm.vmoptions");
401	        let config = SyncConfig::default();
402	        assert_eq!(
403	            canonical_relative_path("pycharm.vmoptions", &ide, &config),
404	            "idea.vmoptions"
405	        );
406	        assert_eq!(
407	            target_relative_path("idea.vmoptions", &ide, &config),
408	            "pycharm.vmoptions"
409	        );
410	    }
411	
412	    #[test]
413	    fn discovery_applies_manifest_and_excludes() {
414	        let directory = tempfile::tempdir().unwrap();
415	        let root = directory.path();
416	        std::fs::create_dir_all(root.join("options")).unwrap();
417	        std::fs::create_dir_all(root.join("plugins/some-plugin")).unwrap();
418	        std::fs::write(root.join("options/editor.xml"), "<application />").unwrap();
419	        std::fs::write(root.join("options/window.state.xml"), "<application />").unwrap();
420	        std::fs::write(root.join("plugins/some-plugin/a.jar"), "binary").unwrap();
421	        std::fs::write(root.join("idea.key"), "secret").unwrap();
422	
423	        let ide = ide_at(root, "IntelliJIdea", "idea.vmoptions");
424	        let found = discover(&ide, &SyncConfig::default(), &[]).unwrap();
425	
426	        assert!(found.contains_key("options/editor.xml"));
427	        assert!(
428	            !found.contains_key("options/window.state.xml"),
429	            "machine-local"
430	        );
431	        assert!(!found.keys().any(|key| key.starts_with("plugins/")));
432	        assert!(!found.contains_key("idea.key"), "credentials never sync");
433	    }
434	
435	    #[test]
436	    fn explicit_include_overrides_the_manifest() {
437	        let directory = tempfile::tempdir().unwrap();
438	        let root = directory.path();
439	        std::fs::write(root.join("idea.vmoptions"), "-Xmx4g").unwrap();
440	
441	        let ide = ide_at(root, "IntelliJIdea", "idea.vmoptions");
442	        let mut config = SyncConfig::default();
443	        assert!(
444	            !discover(&ide, &config, &[])
445	                .unwrap()
446	                .contains_key("idea.vmoptions"),
447	            "not in the built-in manifest"
448	        );
449	
450	        config.jetbrains.explicit_include = vec!["*.vmoptions".to_string()];
451	        assert!(
452	            discover(&ide, &config, &[])
453	                .unwrap()
454	                .contains_key("idea.vmoptions")
455	        );
456	    }
