458	    #[test]
459	    fn the_manifest_is_pooled_across_ides() {
460	        let directory = tempfile::tempdir().unwrap();
461	        let with_tree = directory.path().join("IntelliJIdea2026.2");
462	        let without_tree = directory.path().join("WebStorm2026.2");
463	        std::fs::create_dir_all(with_tree.join("settingsSync/options")).unwrap();
464	        std::fs::create_dir_all(without_tree.join("options")).unwrap();
465	        std::fs::write(
466	            with_tree.join("settingsSync/options/laf.xml"),
467	            "<application />",
468	        )
469	        .unwrap();
470	
471	        let first = ide_at(&with_tree, "IntelliJIdea", "idea.vmoptions");
472	        let second = ide_at(&without_tree, "WebStorm", "webstorm.vmoptions");
473	        let manifest = learned_manifest(&[&first, &second], &[]);
474	        assert!(manifest.contains(&"options/laf.xml".to_string()));
475	        assert_eq!(
476	            observed_manifest(&[&first, &second]),
477	            vec!["options/laf.xml".to_string()],
478	            "only what an IDE proved is published back to the store"
479	        );
480	
481	        // The IDE with no tree of its own still gets the pooled allowlist, and
482	        // nothing outside it — `other.xml` is not roamed by JetBrains.
483	        std::fs::write(without_tree.join("options/laf.xml"), "<application />").unwrap();
484	        std::fs::write(without_tree.join("options/other.xml"), "<application />").unwrap();
485	        let found = discover(&second, &SyncConfig::default(), &manifest).unwrap();
486	        assert!(found.contains_key("options/laf.xml"));
487	        assert!(!found.contains_key("options/other.xml"));
488	    }
489	
490	    #[test]
491	    fn without_any_learned_tree_the_builtin_list_applies() {
492	        let directory = tempfile::tempdir().unwrap();
493	        let ide = ide_at(directory.path(), "WebStorm", "webstorm.vmoptions");
494	        let manifest = learned_manifest(&[&ide], &[]);
495	        assert!(manifest.contains(&"options/editor.xml".to_string()));
496	        assert!(
497	            !manifest.iter().any(|entry| entry == "options/other.xml"),
498	            "per-machine UI state must never be in the fallback list"
499	        );
500	    }
