502	    /// The point of remembering: a machine with no `settingsSync` tree of its
503	    /// own still syncs what another machine proved roams.
504	    #[test]
505	    fn a_remembered_entry_widens_the_manifest() {
506	        let directory = tempfile::tempdir().unwrap();
507	        let ide = ide_at(directory.path(), "WebStorm", "webstorm.vmoptions");
508	        let remembered = vec!["options/unusual.xml".to_string()];
509	        let manifest = learned_manifest(&[&ide], &remembered);
510	        assert!(manifest.contains(&"options/unusual.xml".to_string()));
511	        // Remembering must not narrow the floor the built-in list provides.
512	        assert!(manifest.contains(&"options/editor.xml".to_string()));
513	        assert!(
514	            observed_manifest(&[&ide]).is_empty(),
515	            "this machine observed nothing, so it publishes nothing"
516	        );
517	    }
