519	    #[test]
520	    fn settings_sync_tombstones_are_not_adopted() {
521	        let directory = tempfile::tempdir().unwrap();
522	        let root = directory.path();
523	        std::fs::create_dir_all(root.join("settingsSync/options")).unwrap();
524	        std::fs::write(root.join("settingsSync/options/terminal.xml"), "DELETED").unwrap();
525	        std::fs::write(root.join("settingsSync/options/laf.xml"), "<application />").unwrap();
526	
527	        let ide = ide_at(root, "IntelliJIdea", "idea.vmoptions");
528	        let manifest = settings_sync_manifest(&ide);
529	        assert!(manifest.contains(&"options/laf.xml".to_string()));
530	        assert!(!manifest.contains(&"options/terminal.xml".to_string()));
531	    }
