    /// Never offer a plugin to matching IDEs.
    Deny {
        /// Plugin ID from its descriptor.
        id: String,
        /// Glob over IDE directory name or product; every IDE by default.
        #[arg(long = "ide", default_value = "*")]
        ide: String,
    },
}

pub fn run() -> anyhow::Result<()> {
    let cli = Cli::parse();
    match cli.command {
        Command::Init { remote, machine } => init(cli.config_dir, remote, machine)?,
        Command::Status => {
            let mut engine = Engine::open(cli.config_dir)?;
            let options = SyncOptions {
                dry_run: true,
                ..SyncOptions::default()
            };
            let report = engine.sync_reporting(&options, &mut Progress::new())?;
            print!("{}", render_with(&report, cli.verbose, Style::auto()));
        }
        Command::Sync {
            dry_run,
            prefer,
            ides,
            collect_only,
            no_install_plugins,
            install_plugins: _,
            message,
        } => {
            let mut engine = Engine::open(cli.config_dir)?;
            let options = SyncOptions {
                dry_run,
                policy: prefer.into(),
                message,
                only: ides,
                collect_only,
                install_plugins: !no_install_plugins,
            };

1	//! Keeping only settings the user actually chose.
2	//!
3	//! The IntelliJ platform already does most of this work: when a component's
4	//! state equals the state produced by its default constructor, nothing is
5	//! written to XML at all. So a live `options/*.xml` is close to a diff against
6	//! defaults before `jbsync` touches it.
7	//!
8	//! What remains is residue of three kinds, and each gets a declarative rule
9	//! rather than bespoke code:
10	//!
11	//!   * components that serialize a whole map, including untouched entries
12	//!     (tutorial progress, inlay-hint tables);
13	//!   * values the IDE set for itself rather than for the user (registry keys
14	//!     carrying `source="SYSTEM"` or `"MANAGER"`, one-shot migration flags);
15	//!   * components that persist only a schema version and no settings.
16	//!
17	//! Rules are data, so covering a newly noisy component is a table entry here
18	//! or an `[[xml.omit]]` block in `sync.toml` — never a new code path.
19	
20	use crate::{
21	    config::XmlOmitRule, settings::defaults::ProductDefaults, xml::dom::Element, xml::project,
22	};
23	
24	/// Attributes that describe the file format rather than a user's choice. A
25	/// component carrying only these, with no children, holds no settings.
26	const BOOKKEEPING_ATTRIBUTES: [&str; 2] = ["name", "version"];
27	
28	struct Builtin {
29	    file: &'static str,
30	    component: Option<&'static str>,
31	    element: &'static str,
32	    attribute: &'static str,
33	    equals: &'static str,
34	    reason: &'static str,
35	}
36	
37	/// Values written by the IDE for its own purposes. Registry keys record where
38	/// they came from; anything not attributable to the user is not a setting we
39	/// want to carry between machines.
40	const BUILTINS: &[Builtin] = &[
41	    Builtin {
42	        file: "options/ide.general.xml",
43	        component: Some("Registry"),
44	        element: "entry",
45	        attribute: "source",
46	        equals: "SYSTEM",
47	        reason: "registry key set by the IDE, not the user",
48	    },
49	    Builtin {
50	        file: "options/ide.general.xml",
51	        component: Some("Registry"),
52	        element: "entry",
53	        attribute: "source",
54	        equals: "MANAGER",
55	        reason: "registry key managed centrally, not by the user",
56	    },
57	    Builtin {
58	        file: "options/ide-features-trainer.xml",
59	        component: Some("LessonStateBase"),
60	        element: "entry",
61	        attribute: "value",
62	        equals: "NOT_PASSED",
63	        reason: "tutorial never started",
64	    },
65	    Builtin {
66	        file: "options/*.xml",
67	        component: None,
68	        element: "option",
69	        attribute: "name",
70	        equals: "MIGRATE_OLD_SETTINGS",
71	        reason: "one-shot settings migration flag",
72	    },
73	    Builtin {
74	        file: "options/other.xml",
75	        component: Some("LangManager"),
76	        element: "entry",
77	        attribute: "key",
78	        equals: "JAVA",
79	        reason: "per-installation language state",
80	    },
81	];
