83	#[derive(Debug, Clone, PartialEq, Eq)]
84	pub struct Removal {
85	    /// Human-readable address, as shown in reports.
86	    pub path: String,
87	    pub reason: String,
88	}
89	
90	#[derive(Debug, Clone, Default)]
91	pub struct PruneOutcome {
92	    pub removed: Vec<Removal>,
93	    /// True when nothing worth storing survived, so the file itself can be
94	    /// dropped from the store.
95	    pub is_empty: bool,
96	}
97	
98	fn file_matches(pattern: &str, relative: &str) -> bool {
99	    globset::Glob::new(pattern).is_ok_and(|glob| glob.compile_matcher().is_match(relative))
100	}
101	
102	/// True when `element` is one the rule targets, given the component it sits in.
103	fn rule_matches(
104	    element: &Element,
105	    component: Option<&str>,
106	    rule_component: Option<&str>,
107	    rule_element: &str,
108	    attribute: Option<&str>,
109	    option: Option<&str>,
110	    equals: &str,
111	) -> bool {
112	    if element.name != rule_element {
113	        return false;
114	    }
115	    if let Some(wanted) = rule_component
116	        && component != Some(wanted)
117	    {
118	        return false;
119	    }
120	    if let Some(name) = option {
121	        return element.attributes.get("name").map(String::as_str) == Some(name);
122	    }
123	    let Some(attribute) = attribute else {
124	        return false;
125	    };
126	    element.attributes.get(attribute).map(String::as_str) == Some(equals)
127	}
128	
129	/// Removes non-setting content from `root`, reporting what went and why.
130	/// `defaults`, when present, are the values this product shipped with, captured
131	/// from an install nobody had opened yet. A setting still holding its default is
132	/// not a choice, so it is removed here — before the bottom-up cleanup, so the
133	/// component it lived in disappears too rather than lingering as an empty shell.
134	pub fn prune_document(
135	    relative: &str,
136	    root: &mut Element,
137	    rules: &[XmlOmitRule],
138	    use_builtins: bool,
139	    defaults: Option<&ProductDefaults>,
140	) -> PruneOutcome {
141	    let mut removed = Vec::new();
142	
143	    if use_builtins {
144	        for rule in BUILTINS
145	            .iter()
146	            .filter(|rule| file_matches(rule.file, relative))
147	        {
148	            apply(
149	                root,
150	                None,
151	                "",
152	                rule.component,
153	                rule.element,
154	                Some(rule.attribute),
155	                None,
156	                rule.equals,
157	                rule.reason,
158	                &mut removed,
159	            );
160	        }
161	    }
162	    for rule in rules
163	        .iter()
164	        .filter(|rule| file_matches(&rule.file, relative))
165	    {
166	        let reason = format!("excluded by {}", rule.file);
167	        apply(
168	            root,
169	            None,
170	            "",
171	            rule.component.as_deref(),
172	            &rule.element,
173	            rule.attribute.as_deref(),
174	            rule.option.as_deref(),
175	            &rule.equals,
176	            &reason,
177	            &mut removed,
178	        );
179	    }
180	
181	    if let Some(defaults) = defaults {
182	        let untouched: Vec<String> = project::project(root)
183	            .into_iter()
184	            .filter(|(address, value)| defaults.value(relative, address) == Some(value.as_str()))
185	            .map(|(address, _)| address)
186	            .collect();
187	        for address in untouched {
188	            project::remove_leaf(root, &address);
189	            removed.push(Removal {
190	                path: project::sugar(&address),
191	                reason: "unchanged from this product's default".to_string(),
192	            });
193	        }
194	    }
195	
196	    // Prune bottom-up first: a component only looks settingless once the
197	    // wrappers its removed entries lived in have themselves gone.
198	    project::prune_empty(root);
199	    drop_settingless_components(root, &mut removed);
200	
201	    PruneOutcome {
202	        is_empty: root.children.is_empty() && root.attributes.is_empty(),
203	        removed,
204	    }
205	}
206	
207	#[allow(clippy::too_many_arguments)]
208	fn apply(
209	    element: &mut Element,
210	    component: Option<&str>,
211	    path: &str,
212	    rule_component: Option<&str>,
213	    rule_element: &str,
214	    attribute: Option<&str>,
215	    option: Option<&str>,
216	    equals: &str,
217	    reason: &str,
218	    removed: &mut Vec<Removal>,
219	) {
220	    // A `<component name=...>` establishes the scope rules are written against.
221	    let scope = if element.name == "component" {
222	        element.attributes.get("name").map(String::as_str)
223	    } else {
224	        component
225	    };
226	
227	    element.children.retain(|child| {
228	        let matched = rule_matches(
229	            child,
230	            scope,
231	            rule_component,
232	            rule_element,
233	            attribute,
234	            option,
235	            equals,
236	        );
237	        if matched {
238	            removed.push(Removal {
239	                path: describe(path, child),
240	                reason: reason.to_string(),
241	            });
242	        }
243	        !matched
244	    });
245	
246	    let scope = scope.map(str::to_string);
247	    for child in &mut element.children {
248	        let child_path = describe(path, child);
249	        apply(
250	            child,
251	            scope.as_deref(),
252	            &child_path,
253	            rule_component,
254	            rule_element,
255	            attribute,
256	            option,
257	            equals,
258	            reason,
259	            removed,
260	        );
261	    }
262	}
263	
264	/// A readable address for an element, used only in reports.
265	fn describe(parent_path: &str, element: &Element) -> String {
266	    let own = element
267	        .key_attribute()
268	        .map_or_else(|| element.name.clone(), |(_, value)| value.to_string());
269	    if parent_path.is_empty() {
270	        own
271	    } else {
272	        format!("{parent_path}/{own}")
273	    }
274	}
275	
276	/// Drops components that persist a schema version but no settings.
277	fn drop_settingless_components(root: &mut Element, removed: &mut Vec<Removal>) {
278	    root.children.retain(|child| {
279	        let settingless = child.name == "component"
280	            && child.children.is_empty()
281	            && child.text.is_none()
282	            && child
283	                .attributes
284	                .keys()
285	                .all(|key| BOOKKEEPING_ATTRIBUTES.contains(&key.as_str()));
286	        if settingless {
287	            removed.push(Removal {
288	                path: describe("", child),
289	                reason: "component stores no settings".to_string(),
290	            });
291	        }
292	        !settingless
293	    });
294	}
