1	//! Two-tier configuration: a local, unsynced `config.toml` that only knows how
2	//! to reach the sync-data store and where `JetBrains` lives on this machine, and
3	//! a `sync.toml` that lives *inside* the sync-data store and therefore
4	//! replicates to every machine automatically.
5	
6	use std::{collections::BTreeMap, fmt::Write as _, path::PathBuf};
7	
8	use serde::{Deserialize, Serialize};
9	
10	use crate::error::Result;
11	
12	fn read_toml<T: Default + for<'de> Deserialize<'de>>(path: &std::path::Path) -> Result<T> {
13	    if !path.exists() {
14	        return Ok(T::default());
15	    }
16	    let contents = std::fs::read_to_string(path)?;
17	    toml::from_str(&contents).map_err(|error| {
18	        crate::error::JbsyncError::configuration(format!("{}: {error}", path.display()))
19	    })
20	}
21	
22	fn write_toml<T: Serialize>(path: &std::path::Path, value: &T) -> Result<()> {
23	    let encoded = toml::to_string_pretty(value)
24	        .map_err(|error| crate::error::JbsyncError::configuration(error.to_string()))?;
25	    if let Some(parent) = path.parent() {
26	        std::fs::create_dir_all(parent)?;
27	    }
28	    std::fs::write(path, encoded)?;
29	    Ok(())
30	}
