183	/// What happened when a rule was written, so the caller can say so.
184	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
185	pub enum RuleWrite {
186	    Added,
187	    /// The identical rule was already there, so the file was left alone.
188	    AlreadyPresent,
189	}
