191	/// Appends a `[[plugins.rule]]` block to `sync.toml`.
192	///
193	/// Appends rather than re-serializing the whole config: `SyncConfig` would
194	/// round-trip every default into the file and drop the comments a person wrote
195	/// there. A new array-of-tables at the end is valid TOML whatever precedes it,
196	/// and last-match-wins means a later rule is also the one that takes effect.
197	pub fn append_plugin_rule(path: &std::path::Path, rule: &PluginRule) -> Result<RuleWrite> {
198	    let existing: SyncConfig = read_toml(path)?;
199	    if existing.plugins.rule.iter().any(|current| {
200	        current.id == rule.id && current.ide == rule.ide && current.action == rule.action
201	    }) {
202	        return Ok(RuleWrite::AlreadyPresent);
203	    }
204	
205	    let mut contents = if path.exists() {
206	        std::fs::read_to_string(path)?
207	    } else {
208	        String::new()
209	    };
210	    if !contents.is_empty() && !contents.ends_with('\n') {
211	        contents.push('\n');
212	    }
213	    if !contents.is_empty() {
214	        contents.push('\n');
215	    }
216	    let _ = write!(
217	        contents,
218	        "[[plugins.rule]]\nid = \"{}\"\nide = \"{}\"\naction = \"{}\"\n",
219	        toml_escape(&rule.id),
220	        toml_escape(&rule.ide),
221	        toml_escape(&rule.action)
222	    );
223	
224	    if let Some(parent) = path.parent() {
225	        std::fs::create_dir_all(parent)?;
226	    }
227	    std::fs::write(path, contents)?;
228	    Ok(RuleWrite::Added)
229	}
