312	/// Sanitizes a raw machine identifier to `[A-Za-z0-9._-]`, matching the
313	/// filename-safety constraint on `machines/<id>.toml`.
314	pub fn sanitize_machine_id(raw: &str) -> String {
315	    let cleaned: String = raw
316	        .chars()
317	        .map(|ch| {
318	            if ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-') {
319	                ch
320	            } else {
321	                '-'
322	            }
323	        })
324	        .collect();
325	    let trimmed = cleaned.trim_matches('-');
326	    if trimmed.is_empty() {
327	        "machine".to_string()
328	    } else {
329	        trimmed.to_string()
330	    }
331	}
