333	pub fn machine_id(explicit: Option<&str>) -> String {
334	    let raw = explicit
335	        .map(str::to_string)
336	        .or_else(|| std::env::var("JBSYNC_MACHINE").ok())
337	        .or_else(|| hostname().map(|name| name.split('.').next().unwrap_or(&name).to_string()))
338	        .unwrap_or_else(|| "machine".to_string());
339	    sanitize_machine_id(&raw)
340	}
