1	//! A flat, stable projection of a settings document.
2	//!
3	//! Every leaf (an attribute value, or an element's text) gets an address built
4	//! from its ancestors. Two documents can then be compared, and merged, one
5	//! setting at a time instead of one file at a time. The projection is a view:
6	//! the XML tree remains the source of truth, and merged leaves are written
7	//! back into a real tree so nothing outside the changed setting is disturbed.
8	//!
9	//! Address grammar, `/`-separated:
10	//!   `tag[attr=value]`  element identified by its key attribute
11	//!   `tag#n`            the n-th sibling sharing `tag`, when it has no key
12	//!   `@attr`            terminal: an attribute value
13	//!   `#text`            terminal: character data
14	
15	use std::collections::BTreeMap;
16	
17	use super::dom::Element;
18	
19	/// Leaf address to value. Ordered, so serialization and reports are stable.
20	pub type Projection = BTreeMap<String, String>;
21	
22	const TEXT_LEAF: &str = "#text";
23	
24	/// The address of `element` relative to its parent. `same_tag_index` is the
25	/// element's position among siblings that share its tag name.
26	fn segment(element: &Element, same_tag_index: usize) -> String {
27	    element.key_attribute().map_or_else(
28	        || format!("{}#{same_tag_index}", element.name),
29	        |(attribute, value)| format!("{}[{attribute}={value}]", element.name),
30	    )
31	}
32	
33	/// Addresses of every child, paired with its index, in document order.
34	fn child_segments(parent: &Element) -> Vec<(usize, String)> {
35	    let mut counters: BTreeMap<&str, usize> = BTreeMap::new();
36	    parent
37	        .children
38	        .iter()
39	        .enumerate()
40	        .map(|(index, child)| {
41	            let counter = counters.entry(child.name.as_str()).or_default();
42	            let address = segment(child, *counter);
43	            *counter += 1;
44	            (index, address)
45	        })
46	        .collect()
47	}
48	
49	/// Flattens `root` into leaf addresses. The root's own tag is not part of any
50	/// address: a document is only ever compared against the same file from
51	/// another machine, so the root is shared context rather than information.
52	pub fn project(root: &Element) -> Projection {
53	    let mut flattened = Projection::new();
54	    collect(root, "", &mut flattened);
55	    flattened
56	}
57	
58	fn collect(element: &Element, prefix: &str, output: &mut Projection) {
59	    let join = |leaf: &str| {
60	        if prefix.is_empty() {
61	            leaf.to_string()
62	        } else {
63	            format!("{prefix}/{leaf}")
64	        }
65	    };
66	
67	    // The key attribute is already encoded in this element's own address, so
68	    // emitting it again would only add noise to every diff.
69	    let key = element.key_attribute().map(|(attribute, _)| attribute);
70	    for (attribute, value) in &element.attributes {
71	        if Some(attribute.as_str()) != key {
72	            output.insert(join(&format!("@{attribute}")), value.clone());
73	        }
74	    }
75	    if let Some(text) = &element.text {
76	        output.insert(join(TEXT_LEAF), text.clone());
77	    }
78	    for (index, address) in child_segments(element) {
79	        collect(&element.children[index], &join(&address), output);
80	    }
81	}
82	
83	/// Rewrites an address for display, collapsing JetBrains' boilerplate so a
84	/// report reads like the settings UI rather than like XPath.
85	///
86	/// `component[name=Editor]/option[name=Font]/map#0/entry[key=size]/@value`
87	/// becomes `Editor/Font/size`.
88	pub fn sugar(path: &str) -> String {
89	    let mut parts: Vec<String> = Vec::new();
90	    for raw in path.split('/') {
91	        if matches!(raw, "map#0" | "list#0" | "set#0" | "value#0") {
92	            continue;
93	        }
94	        let simplified = strip_wrapper(raw, "component", "name")
95	            .or_else(|| strip_wrapper(raw, "option", "name"))
96	            .or_else(|| strip_wrapper(raw, "entry", "key"));
97	        match simplified {
98	            Some(value) => parts.push(value),
99	            None if raw == "@value" => {}
100	            // `@themeId` is the setting's name to a reader; the `@` only tells
101	            // the merge that it addresses an attribute.
102	            None if raw.starts_with('@') => parts.push(raw[1..].to_string()),
103	            // `laf#0` is the first and usually only `laf` element. The index
104	            // matters to the merge and means nothing to a reader, so keep it
105	            // only where it actually distinguishes siblings.
106	            None => parts.push(raw.strip_suffix("#0").unwrap_or(raw).to_string()),
107	        }
108	    }
109	    if parts.is_empty() {
110	        path.to_string()
111	    } else {
112	        parts.join("/")
113	    }
114	}
115	
116	fn strip_wrapper(segment: &str, tag: &str, attribute: &str) -> Option<String> {
117	    segment
118	        .strip_prefix(&format!("{tag}[{attribute}="))?
119	        .strip_suffix(']')
120	        .map(str::to_string)
121	}
122	
123	/// Writes `value` at `path`, creating any missing ancestors by copying their
124	/// shells from `donor` (the tree the leaf is coming from). Returns false when
125	/// `donor` does not actually contain the path, which would leave the target in
126	/// a half-built state.
127	pub fn set_leaf(target: &mut Element, donor: &Element, path: &str, value: &str) -> bool {
128	    let mut segments: Vec<&str> = path.split('/').collect();
129	    let Some(leaf) = segments.pop() else {
130	        return false;
131	    };
132	
133	    let mut cursor = target;
134	    let mut source = donor;
135	    for wanted in segments {
136	        let Some(donor_index) = find_child(source, wanted) else {
137	            return false;
138	        };
139	        source = &source.children[donor_index];
140	        if let Some(index) = find_child(cursor, wanted) {
141	            cursor = &mut cursor.children[index];
142	        } else {
143	            cursor.children.push(source.shell());
144	            let last = cursor.children.len() - 1;
145	            cursor = &mut cursor.children[last];
146	        }
147	    }
148	
149	    if leaf == TEXT_LEAF {
150	        cursor.text = Some(value.to_string());
151	    } else if let Some(attribute) = leaf.strip_prefix('@') {
152	        cursor
153	            .attributes
154	            .insert(attribute.to_string(), value.to_string());
155	    } else {
156	        return false;
157	    }
158	    true
159	}
160	
161	/// Removes the leaf at `path`, then drops any ancestor left with nothing to
162	/// serialize.
163	pub fn remove_leaf(target: &mut Element, path: &str) {
164	    let mut segments: Vec<&str> = path.split('/').collect();
165	    let Some(leaf) = segments.pop() else {
166	        return;
167	    };
168	
169	    let mut cursor = &mut *target;
170	    for wanted in &segments {
171	        match find_child(cursor, wanted) {
172	            Some(index) => cursor = &mut cursor.children[index],
173	            None => return,
174	        }
175	    }
176	    if leaf == TEXT_LEAF {
177	        cursor.text = None;
178	    } else if let Some(attribute) = leaf.strip_prefix('@') {
179	        cursor.attributes.remove(attribute);
180	    }
181	    prune_empty(target);
182	}
183	
184	/// Drops elements that no longer carry any value. A parent is only removed
185	/// once all of its children have been, so pruning is bottom-up.
186	pub fn prune_empty(element: &mut Element) {
187	    for child in &mut element.children {
188	        prune_empty(child);
189	    }
190	    element.children.retain(|child| !child.is_valueless());
191	}
192	
193	fn find_child(parent: &Element, wanted: &str) -> Option<usize> {
194	    child_segments(parent)
195	        .into_iter()
196	        .find(|(_, address)| address == wanted)
197	        .map(|(index, _)| index)
198	}
