1	//! A minimal DOM for JetBrains settings files.
2	//!
3	//! Child order is preserved because some JetBrains elements (`<list>`, ordered
4	//! `<filter>` chains) are order-sensitive. Attributes are held in a `BTreeMap`,
5	//! so serialization is canonical without reordering anything that carries
6	//! meaning. JetBrains already writes components and options alphabetically, so
7	//! preserving document order still yields stable, machine-independent files.
8	
9	use std::{collections::BTreeMap, fmt::Write as _};
10	
11	/// Attributes JetBrains uses to identify a sibling, most specific first. A
12	/// child carrying one of these is addressed by its value rather than by
13	/// position, so a projected path survives siblings being inserted or removed.
14	pub const KEY_ATTRIBUTES: [&str; 9] = [
15	    "name", "key", "id", "class", "type", "language", "scheme", "ext", "pattern",
16	];
17	
18	/// Elements whose identifying attribute is only an address, never the setting
19	/// itself. Everything else is assumed to mean something by existing.
20	pub const WRAPPER_ELEMENTS: [&str; 5] = ["option", "entry", "map", "list", "set"];
21	
22	#[derive(Debug, Clone, PartialEq, Eq, Default)]
23	pub struct Element {
24	    pub name: String,
25	    pub attributes: BTreeMap<String, String>,
26	    pub children: Vec<Element>,
27	    /// Trimmed character data. JetBrains settings files never mix text and
28	    /// element children, so a single optional string is sufficient.
29	    pub text: Option<String>,
30	}
31	
32	#[derive(Debug)]
33	pub struct ParseError(pub String);
34	
35	impl std::fmt::Display for ParseError {
36	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
37	        formatter.write_str(&self.0)
38	    }
39	}
40	
41	impl std::error::Error for ParseError {}
42	
43	impl Element {
44	    pub fn new(name: impl Into<String>) -> Self {
45	        Self {
46	            name: name.into(),
47	            ..Self::default()
48	        }
49	    }
50	
51	    /// The identifying attribute for this element, if it carries one.
52	    pub fn key_attribute(&self) -> Option<(&str, &str)> {
53	        KEY_ATTRIBUTES.iter().find_map(|attribute| {
54	            self.attributes
55	                .get(*attribute)
56	                .map(|value| (*attribute, value.as_str()))
57	        })
58	    }
59	
60	    /// True when the element carries no value of its own, and can therefore be
61	    /// pruned once a merge or a prune rule removed its last leaf.
62	    ///
63	    /// The distinction that matters: in a *wrapper* element the name is only an
64	    /// address and the value lives in a sibling attribute, so `<option
65	    /// name="map" />` with an emptied map holds nothing. In a domain element
66	    /// the name is the payload — `<global_color_scheme name="Islands Dark" />`
67	    /// *is* the colour-scheme setting — so it must survive. Anything with
68	    /// children, text, or an attribute beyond its own address is kept either
69	    /// way.
70	    pub fn is_valueless(&self) -> bool {
71	        if !self.children.is_empty() || self.text.is_some() {
72	            return false;
73	        }
74	        if self.attributes.is_empty() {
75	            // A bare <map />, <list /> or <set />: pure structure.
76	            return true;
77	        }
78	        WRAPPER_ELEMENTS.contains(&self.name.as_str())
79	            && self
80	                .attributes
81	                .keys()
82	                .all(|key| KEY_ATTRIBUTES.contains(&key.as_str()))
83	    }
84	
85	    /// A shallow copy used when a merge needs to graft a donor path onto a
86	    /// tree that does not have those ancestors yet.
87	    #[must_use]
88	    pub fn shell(&self) -> Self {
89	        Self {
90	            name: self.name.clone(),
91	            attributes: self.attributes.clone(),
92	            children: Vec::new(),
93	            text: None,
94	        }
95	    }
96	}
97	
98	pub fn parse(contents: &str) -> Result<Element, ParseError> {
99	    let parsed = xmltree::Element::parse(contents.as_bytes())
100	        .map_err(|error| ParseError(error.to_string()))?;
101	    Ok(convert(&parsed))
102	}
103	
104	fn convert(source: &xmltree::Element) -> Element {
105	    let mut text = String::new();
106	    let mut children = Vec::new();
107	    for node in &source.children {
108	        match node {
109	            xmltree::XMLNode::Element(child) => children.push(convert(child)),
110	            xmltree::XMLNode::Text(chunk) | xmltree::XMLNode::CData(chunk) => text.push_str(chunk),
111	            _ => {}
112	        }
113	    }
114	    let trimmed = text.trim();
115	    Element {
116	        name: source.name.clone(),
117	        attributes: source
118	            .attributes
119	            .iter()
120	            .map(|(key, value)| (key.clone(), value.clone()))
121	            .collect(),
122	        children,
123	        text: (!trimmed.is_empty()).then(|| trimmed.to_string()),
124	    }
125	}
126	
127	/// Serializes to the same dialect JetBrains itself writes: a single-quoted
128	/// declaration, two-space indentation, and a space before every `/>`.
129	pub fn serialize(root: &Element) -> String {
130	    let mut output = String::from("<?xml version='1.0' encoding='utf-8'?>\n");
131	    write_element(&mut output, root, 0);
132	    output
133	}
134	
135	fn write_element(output: &mut String, element: &Element, depth: usize) {
136	    let indent = "  ".repeat(depth);
137	    let _ = write!(output, "{indent}<{}", element.name);
138	    for (key, value) in &element.attributes {
139	        let _ = write!(output, " {key}=\"{}\"", escape_attribute(value));
140	    }
141	
142	    if element.children.is_empty() && element.text.is_none() {
143	        output.push_str(" />\n");
144	        return;
145	    }
146	
147	    output.push('>');
148	    if let Some(text) = &element.text
149	        && element.children.is_empty()
150	    {
151	        let _ = writeln!(output, "{}</{}>", escape_text(text), element.name);
152	        return;
153	    }
154	
155	    output.push('\n');
156	    for child in &element.children {
157	        write_element(output, child, depth + 1);
158	    }
159	    let _ = writeln!(output, "{indent}</{}>", element.name);
160	}
161	
162	fn escape_attribute(value: &str) -> String {
163	    let mut escaped = String::with_capacity(value.len());
164	    for character in value.chars() {
165	        match character {
166	            '&' => escaped.push_str("&amp;"),
167	            '<' => escaped.push_str("&lt;"),
168	            '>' => escaped.push_str("&gt;"),
169	            '"' => escaped.push_str("&quot;"),
170	            // Whitespace inside an attribute is normalized to a space by any
171	            // conforming parser, so it must survive as a character reference.
172	            '\n' => escaped.push_str("&#10;"),
173	            '\r' => escaped.push_str("&#13;"),
174	            '\t' => escaped.push_str("&#9;"),
175	            other => escaped.push(other),
176	        }
177	    }
178	    escaped
179	}
180	
181	fn escape_text(value: &str) -> String {
182	    let mut escaped = String::with_capacity(value.len());
183	    for character in value.chars() {
184	        match character {
185	            '&' => escaped.push_str("&amp;"),
186	            '<' => escaped.push_str("&lt;"),
187	            '>' => escaped.push_str("&gt;"),
188	            other => escaped.push(other),
189	        }
190	    }
191	    escaped
192	}
