194	#[cfg(test)]
195	mod tests {
196	    use super::*;
197	
198	    #[test]
199	    fn round_trips_a_typical_options_file() {
200	        let source = "<?xml version='1.0' encoding='utf-8'?>\n<application>\n  <component name=\"GeneralSettings\">\n    <option name=\"reopenLastProject\" value=\"false\" />\n  </component>\n</application>";
201	        let parsed = parse(source).unwrap();
202	        let serialized = serialize(&parsed);
203	        assert_eq!(parse(&serialized).unwrap(), parsed);
204	        assert!(serialized.contains("<option name=\"reopenLastProject\" value=\"false\" />"));
205	    }
206	
207	    #[test]
208	    fn attributes_serialize_in_sorted_order() {
209	        let parsed = parse("<root b=\"2\" a=\"1\" c=\"3\" />").unwrap();
210	        assert!(serialize(&parsed).contains("<root a=\"1\" b=\"2\" c=\"3\" />"));
211	    }
212	
213	    #[test]
214	    fn preserves_child_order() {
215	        let parsed = parse("<list><item value=\"z\" /><item value=\"a\" /></list>").unwrap();
216	        let serialized = serialize(&parsed);
217	        let first = serialized.find("\"z\"").unwrap();
218	        let second = serialized.find("\"a\"").unwrap();
219	        assert!(first < second, "ordered children must not be sorted");
220	    }
221	
222	    #[test]
223	    fn escapes_significant_whitespace_in_attributes() {
224	        let parsed = parse("<root value=\"a&#10;b\" />").unwrap();
225	        let serialized = serialize(&parsed);
226	        assert!(serialized.contains("&#10;"));
227	        assert_eq!(parse(&serialized).unwrap(), parsed);
228	    }
