230	    #[test]
231	    fn keeps_element_text() {
232	        let parsed = parse("<place>Java: comments</place>").unwrap();
233	        assert_eq!(parsed.text.as_deref(), Some("Java: comments"));
234	        assert_eq!(parse(&serialize(&parsed)).unwrap(), parsed);
235	    }
