237	    #[test]
238	    fn a_domain_element_named_by_its_value_is_not_valueless() {
239	        // The colour scheme setting *is* the name on this element.
240	        let parsed = parse(r#"<global_color_scheme name="Islands Dark" />"#).unwrap();
241	        assert!(!parsed.is_valueless());
242	    }
243	
244	    #[test]
245	    fn an_emptied_wrapper_is_valueless() {
246	        let parsed = parse(r#"<option name="map" />"#).unwrap();
247	        assert!(parsed.is_valueless());
248	        assert!(parse("<map />").unwrap().is_valueless());
249	        assert!(parse(r#"<entry key="a" />"#).unwrap().is_valueless());
250	    }
