1	//! Orchestration: what actually happens when you run `jbsync sync`.
2	//!
3	//! A sync is two reconciliations, both using the same three-way merge:
4	//!
5	//! 1. **Store against the other machines.** Whatever the backend reports as
6	//!    incoming is merged into the local copy of the store, and the result is
7	//!    recorded as reconciled.
8	//! 2. **Each IDE against the store.** Every IDE contributes its settings and
9	//!    receives everyone else's. Doing the IDEs one after another means two IDEs
10	//!    that changed different settings both get their way, and two IDEs that
11	//!    changed the *same* setting produce exactly one reported conflict.
12	//!
13	//! The two directions are deliberately asymmetric. What goes *into* the store
14	//! is pruned down to genuine user choices. What comes *out* is applied to the
15	//! IDE's real file as individual settings, so everything pruning removed — and
16	//! everything the IDE keeps that jbsync does not manage — stays untouched.
17	
18	use std::{
19	    collections::BTreeSet,
20	    path::{Path, PathBuf},
21	};
22	
23	use super::{
24	    merge::{self, ConflictPolicy, FileMerge},
25	    report::{FileReport, IdeReport, SyncReport},
26	};
27	use crate::{
28	    backend::{Backend, Published, git::GitBackend},
29	    config::{self, LocalConfig, MachineConfig, SyncConfig},
30	    error::{JbsyncError, Result},
31	    ide::{self, Ide},
32	    paths::Paths,
33	    plugins,
34	    progress::Progress,
35	    settings::{defaults, manifest, prune, roamable},
36	    xml::{dom, project},
37	};
38	
39	/// Settings live under this prefix inside the store, keeping them clearly
40	/// separate from jbsync's own files (`sync.toml`, `machines/`, `plugins.json`).
41	const SHARED: &str = "shared";
42	
43	/// Timestamped backup runs kept on disk. Every sync that overwrites anything
44	/// creates one, so without a cap they accumulate for the life of the install.
45	/// Ten is enough to walk back a bad run and small enough to stay unnoticeable.
46	const BACKUP_RUNS_KEPT: usize = 10;
47	
48	/// How many times reconciliation may repeat before it is considered stuck.
49	/// Two passes is the normal case and the third only confirms convergence.
50	const MAX_PASSES: usize = 4;
51	
