87	pub struct Engine {
88	    pub paths: Paths,
89	    pub local: LocalConfig,
90	    pub sync_config: SyncConfig,
91	    pub machine: String,
92	    pub machine_config: MachineConfig,
93	    pub ides: Vec<Ide>,
