97	impl Engine {
98	    pub fn open(config_dir: Option<PathBuf>) -> Result<Self> {
99	        let paths = Paths::discover(config_dir)?;
100	        let local = LocalConfig::load(&paths.local_config_path())?;
101	        let workdir = paths.data_dir(&local.repo);
102	
103	        if local.repo.backend != "git" {
104	            return Err(JbsyncError::configuration(format!(
105	                "unknown backend {:?}. Only \"git\" is implemented; see src/backend.rs \
106	                 for the contract a new backend must satisfy.",
107	                local.repo.backend
108	            )));
109	        }
110	        let backend = Box::new(GitBackend::new(
111	            workdir.clone(),
112	            local.repo.remote.clone(),
113	            local.repo.branch.clone(),
114	        ));
115	        backend.initialize()?;
116	
117	        let mut sync_config = SyncConfig::load(&workdir.join("sync.toml"))?;
118	        let machine = config::machine_id(local.machine.id.as_deref());
119	        let machine_config =
120	            MachineConfig::load(&workdir.join(format!("machines/{machine}.toml")))?;
121	        // This machine's exclusions are folded in here so that discovery has a
122	        // single list to consult, matching how `prune_rules` merges the two
123	        // layers of omit rules.
124	        sync_config
125	            .jetbrains
126	            .exclude
127	            .extend(machine_config.jetbrains.exclude.clone());
128	
129	        let root = local.jetbrains.root.as_deref().map_or_else(
130	            crate::platform::default_jetbrains_root,
131	            |value| {
132	                if value == "auto" {
133	                    crate::platform::default_jetbrains_root()
134	                } else {
135	                    PathBuf::from(value)
136	                }
137	            },
138	        );
139	        let install_roots: Vec<PathBuf> = if local.jetbrains.install_roots.is_empty() {
140	            crate::platform::default_install_roots()
141	        } else {
142	            local
143	                .jetbrains
144	                .install_roots
145	                .iter()
146	                .map(PathBuf::from)
147	                .collect()
148	        };
149	        let metadata = ide::discover_product_metadata(&install_roots);
150	        let ides = ide::discover_ides(&root, &sync_config.jetbrains.ides, &metadata)?;
151	
152	        Ok(Self {
153	            paths,
154	            local,
155	            sync_config,
156	            machine,
157	            machine_config,
158	            ides,
159	            backend,
160	        })
161	    }
162	
163	    pub fn store_root(&self) -> &Path {
164	        self.backend.workdir()
165	    }
