178	    fn selected_ides(&self, only: &[String]) -> Vec<&Ide> {
179	        if only.is_empty() {
180	            return self.ides.iter().collect();
181	        }
182	        self.ides
183	            .iter()
184	            .filter(|candidate| {
185	                only.iter()
186	                    .any(|selector| ide::ide_matches_selector(candidate, selector))
187	            })
188	            .collect()
189	    }
190	
191	    /// The rules that decide what is a user choice, from both config layers.
192	    fn prune_rules(&self) -> Vec<crate::config::XmlOmitRule> {
193	        let mut rules = self.sync_config.xml.omit.clone();
194	        rules.extend(self.machine_config.xml.omit.clone());
195	        rules
196	    }
197	
198	    /// Reduces an IDE's file to what belongs in the store: canonical form, with
199	    /// everything that is not a user choice removed.
200	    fn store_view(
201	        &self,
202	        relative: &str,
203	        raw: &[u8],
204	        defaults: Option<&defaults::ProductDefaults>,
205	    ) -> (Option<Vec<u8>>, Vec<prune::Removal>) {
206	        let Ok(text) = std::str::from_utf8(raw) else {
207	            return (Some(raw.to_vec()), Vec::new());
208	        };
209	        if roamable::is_tombstone(text) {
210	            return (None, Vec::new());
211	        }
212	        let Ok(mut document) = dom::parse(text) else {
213	            return (Some(raw.to_vec()), Vec::new());
214	        };
215	        let outcome = prune::prune_document(
216	            relative,
217	            &mut document,
218	            &self.prune_rules(),
219	            self.sync_config.xml.use_defaults,
220	            defaults.filter(|_| self.sync_config.xml.use_defaults),
221	        );
222	
223	        if outcome.is_empty {
224	            return (None, outcome.removed);
225	        }
226	        (
227	            Some(dom::serialize(&document).into_bytes()),
228	            outcome.removed,
229	        )
230	    }
231	
232	    pub fn sync(&mut self, options: &SyncOptions) -> Result<SyncReport> {
233	        self.sync_reporting(options, &mut Progress::silent())
234	    }
235	
236	    /// As [`Engine::sync`], but showing what it is working on. A sync spends
237	    /// most of its time waiting on `git` and on walking IDE directories, and
238	    /// saying nothing for that long is indistinguishable from a hang.
239	    pub fn sync_reporting(
240	        &mut self,
241	        options: &SyncOptions,
242	        progress: &mut Progress,
243	    ) -> Result<SyncReport> {
244	        // Held for the whole run. A sync reads the IDEs, rewrites the store and
245	        // writes back; two overlapping runs could interleave those steps and
246	        // publish a half-merged result.
247	        let Some(_lock) = self.paths.try_lock()? else {
248	            return Err(JbsyncError::other(
249	                "another jbsync run is in progress; wait for it to finish",
250	            ));
251	        };
252	
253	        let mut report = SyncReport {
254	            machine: self.machine.clone(),
255	            backend: self.backend.describe(),
256	            dry_run: options.dry_run,
257	            ..SyncReport::default()
258	        };
259	
260	        let mut staging = Staging::new(options.dry_run);
261	        progress.step("checking for changes from other machines...");
262	        report.from_remote = self.take_incoming(options, &mut staging)?;
263	
264	        // IDEs are reconciled in sequence, so an IDE handled early cannot know
265	        // about settings a later one is about to contribute. Repeating until
266	        // nothing moves lets those reach every IDE in this run rather than the
267	        // next one. Each pass records what it agreed on, so a pass never
268	        // re-reports the previous pass's work; two passes is the normal case
269	        // and the third only confirms convergence.
270	        for pass in 0..MAX_PASSES {
271	            let outcome = self.reconcile_ides(options, &mut staging, progress, pass)?;
272	            let progressed = outcome.iter().any(|ide| !ide.is_empty());
273	            absorb(&mut report.ides, outcome);
274	            if !progressed {
275	                break;
276	            }
277	            // A debug_assert here meant release builds stopped after the last
278	            // pass and said nothing, so a genuinely unsettled sync looked
279	            // complete. Nothing written is wrong -- every pass is a valid merge
280	            // -- but the run is unfinished, and only the report can say so.
281	            if pass + 1 == MAX_PASSES {
282	                report.warnings.push(format!(
283	                    "reconciliation had not settled after {MAX_PASSES} passes;                      some settings may need another `jbsync sync`.                      Please report this at https://github.com/cdenihan/jbsync/issues"
284	                ));
285	            }
286	        }
287	        progress.step("checking plugins...");
288	        let plugins = self.reconcile_plugins(options)?;
289	        report.plugins = plugins.lines;
290	        report.manifest_changed = plugins.manifest_changed;
291	
292	        if !options.dry_run {
293	            // Best-effort: failing to tidy old backups must never fail a sync
294	            // that already succeeded.
295	            let _ = prune_backups(&self.paths.backups_dir(), BACKUP_RUNS_KEPT);
296	        }
297	
298	        if !options.dry_run && report.changes_the_store() {
299	            progress.step("committing...");
300	            let published = self.backend.publish(&options.message)?;
301	            report.published = match published {
302	                Published::Committed { files, cursor } => Some(format!(
303	                    "{files} file(s) at {}{}",
304	                    short(&cursor),
305	                    // Without a remote the commit never leaves this machine,
306	                    // and saying "published" would imply otherwise.
307	                    if self.local.repo.remote.is_some() {
308	                        ""
309	                    } else {
310	                        " (local store only - `jbsync repo set <url>` to share)"
311	                    }
312	                )),
313	                Published::Unchanged => None,
314	            };
315	        }
316	        progress.clear();
317	        Ok(report)
318	    }
319	
320	    /// Records installed plugins in the store and reports which ones are
321	    /// missing elsewhere, installing them unless `--no-install-plugins` says
322	    /// otherwise. Installing launches the IDE binary and downloads from
323	    /// Marketplace, so a sync can be slow the first time a plugin appears.
324	    fn reconcile_plugins(&self, options: &SyncOptions) -> Result<PluginOutcome> {
325	        if !self.sync_config.plugins.enabled {
326	            return Ok(PluginOutcome::default());
327	        }
328	        let selected = self.selected_ides(&options.only);
329	        let manifest_path = self.store_root().join("plugins.json");
330	        let stored = plugins::Manifest::load(&manifest_path)?;
331	        let observed = plugins::collect(&selected, &self.sync_config);
332	        // Kept to answer "did this run change the manifest", which decides
333	        // whether there is anything to commit. The merge below consumes the
334	        // original.
335	        let before = stored.plugins.clone();
336	
337	        // Union: a plugin another machine published stays in the manifest even
338	        // though it is not installed here.
339	        let mut merged: std::collections::BTreeMap<String, plugins::Plugin> = stored
340	            .plugins
341	            .into_iter()
342	            .map(|plugin| (plugin.id.clone(), plugin))
343	            .collect();
344	        let mut lines = Vec::new();
345	        for plugin in observed.plugins {
346	            let entry = merged.entry(plugin.id.clone());
347	            match entry {
348	                std::collections::btree_map::Entry::Vacant(slot) => {
349	                    lines.push(format!("+ {} ({})", plugin.id, plugin.version));
350	                    slot.insert(plugin);
351	                }
352	                std::collections::btree_map::Entry::Occupied(mut slot) => {
353	                    for product in &plugin.source_products {
354	                        if !slot.get().source_products.contains(product) {
355	                            slot.get_mut().source_products.push(product.clone());
356	                        }
357	                    }
358	                    slot.get_mut().version = plugin.version;
359	                }
360	            }
361	        }
362	        let manifest = plugins::Manifest {
363	            version: 1,
364	            plugins: merged.into_values().collect(),
365	        };
366	        // Rewriting an identical manifest would churn the file's mtime on
367	        // every run for nothing.
368	        let manifest_changed = manifest.plugins != before;
369	        if !options.dry_run && manifest_changed {
370	            manifest.save(&manifest_path)?;
371	        }
372	
373	        for action in plugins::plan_installs(&selected, &manifest, &self.sync_config) {
374	            if action.install {
375	                lines.push(format!("{}: install {}", action.ide, action.plugin));
376	                if !options.dry_run && options.install_plugins {
377	                    plugins::install(
378	                        self.ides
379	                            .iter()
380	                            .find(|ide| directory_name(ide) == action.ide)
381	                            .ok_or_else(|| JbsyncError::other("IDE disappeared mid-sync"))?,
382	                        &action.plugin,
383	                        &self.sync_config.plugins,
384	                    )?;
385	                }
386	            } else {
387	                lines.push(format!(
388	                    "{}: skip {} ({})",
389	                    action.ide, action.plugin, action.reason
390	                ));
391	            }
392	        }
393	        Ok(PluginOutcome {
394	            lines,
395	            manifest_changed,
396	        })
397	    }
