399	    /// Turns off JetBrains' bundled Backup and Sync.
400	    ///
401	    /// Both tools write the same files, so leaving both enabled means they
402	    /// overwrite each other's work in a loop.
403	    pub fn disable_builtin_sync(&self, dry_run: bool) -> Result<Vec<String>> {
404	        const SWITCHES: [(&str, &str, &str); 2] = [
405	            ("settingsSync.xml", "SettingsSyncSettings", "syncEnabled"),
406	            (
407	                "settingsSyncLocal.xml",
408	                "SettingsSyncLocalSettings",
409	                "crossIdeSyncEnabled",
410	            ),
411	        ];
412	        let mut actions = Vec::new();
413	        for ide in &self.ides {
414	            for (file, component_name, option_name) in SWITCHES {
415	                let path = ide.path.join("options").join(file);
416	                let mut root = std::fs::read_to_string(&path)
417	                    .ok()
418	                    .and_then(|text| dom::parse(&text).ok())
419	                    .unwrap_or_else(|| dom::Element::new("application"));
420	
421	                let address =
422	                    format!("component[name={component_name}]/option[name={option_name}]/@value");
423	                if project::project(&root).get(&address).map(String::as_str) == Some("false") {
424	                    continue;
425	                }
426	                actions.push(format!(
427	                    "{}: disable JetBrains Backup and Sync ({option_name})",
428	                    directory_name(ide)
429	                ));
430	                if dry_run {
431	                    continue;
432	                }
433	                // Build the donor so `set_leaf` has ancestors to copy shells from.
434	                let mut donor = dom::Element::new("application");
435	                let mut component = dom::Element::new("component");
436	                component
437	                    .attributes
438	                    .insert("name".to_string(), component_name.to_string());
439	                let mut option = dom::Element::new("option");
440	                option
441	                    .attributes
442	                    .insert("name".to_string(), option_name.to_string());
443	                option
444	                    .attributes
445	                    .insert("value".to_string(), "false".to_string());
446	                component.children.push(option);
447	                donor.children.push(component);
448	
449	                project::set_leaf(&mut root, &donor, &address, "false");
450	                write_or_remove(&path, Some(dom::serialize(&root).as_bytes()))?;
451	            }
452	        }
453	        Ok(actions)
454	    }
