456	    /// Merges whatever other machines have published into the local store copy.
457	    fn take_incoming(
458	        &self,
459	        options: &SyncOptions,
460	        staging: &mut Staging,
461	    ) -> Result<Vec<FileReport>> {
462	        let Some(incoming) = self.backend.incoming()? else {
463	            return Ok(Vec::new());
464	        };
465	        let mut reports = Vec::new();
466	        let mut paths: BTreeSet<String> = incoming.base.keys().cloned().collect();
467	        paths.extend(incoming.remote.keys().cloned());
468	        paths.extend(staging.files_under(self.store_root()));
469	
470	        for relative in paths {
471	            if crate::backend::git::is_internal_path(&relative) {
472	                continue;
473	            }
474	            let absolute = self.store_root().join(&relative);
475	            let local = staging.read(&absolute);
476	            let base = incoming.base.get(&relative).cloned();
477	            let remote = incoming.remote.get(&relative).cloned();
478	
479	            // Only files under `shared/` are IDE settings; the rest is jbsync's
480	            // own configuration and merges as opaque text.
481	            let merged = if relative.starts_with(&format!("{SHARED}/")) {
482	                merge::merge_file(
483	                    base.as_deref(),
484	                    local.as_deref(),
485	                    remote.as_deref(),
486	                    options.policy,
487	                )
488	            } else {
489	                merge::merge_opaque(
490	                    base.as_deref(),
491	                    local.as_deref(),
492	                    remote.as_deref(),
493	                    options.policy,
494	                )
495	            };
496	            if merged.is_noop() {
497	                continue;
498	            }
499	            staging.write(&absolute, merged.content.as_deref())?;
500	            reports.push(FileReport {
501	                path: display_path(&relative),
502	                incoming: merged.incoming,
503	                outgoing: merged.outgoing,
504	                conflicts: merged.conflicts,
505	                pruned: Vec::new(),
506	            });
507	        }
508	
509	        if !options.dry_run {
510	            self.backend.reconcile(&incoming.cursor, &options.message)?;
511	        }
512	        Ok(reports)
513	    }
