515	    /// Reconciles each IDE with the store, in turn.
516	    fn reconcile_ides(
517	        &self,
518	        options: &SyncOptions,
519	        staging: &mut Staging,
520	        progress: &mut Progress,
521	        pass: usize,
522	    ) -> Result<Vec<IdeReport>> {
523	        let mut reports = Vec::new();
524	        let stamp = timestamp();
525	
526	        // Learn the allowlist from every launched IDE, not just the selected
527	        // ones, so `--ide WebStorm` still benefits from IntelliJ's knowledge,
528	        // and fold in what other machines have already taught the store.
529	        let all: Vec<&Ide> = self
530	            .ides
531	            .iter()
532	            .filter(|ide| ide.has_been_launched())
533	            .collect();
534	        let remembered = self.remembered_manifest(staging)?;
535	        let manifest = roamable::learned_manifest(&all, &remembered);
536	        self.remember_manifest(&all, staging)?;
537	
538	        // Capture factory defaults before reconciling, so a product installed
539	        // but not yet opened teaches this very run what its defaults are.
540	        for ide in &self.ides {
541	            if !ide.has_been_launched() {
542	                self.capture_defaults(ide, &manifest, staging)?;
543	            }
544	        }
545	
546	        let selected = self.selected_ides(&options.only);
547	        let total = selected.len();
548	        for (index, ide) in selected.into_iter().enumerate() {
549	            progress.step(&format!(
550	                "pass {} - {} ({}/{total})...",
551	                pass + 1,
552	                directory_name(ide),
553	                index + 1
554	            ));
555	            // An IDE that has never been started has only factory defaults to
556	            // offer, and the first-run import wizard may discard anything
557	            // written into it. Report it rather than silently skipping.
558	            if !ide.has_been_launched() {
559	                reports.push(IdeReport {
560	                    directory: directory_name(ide),
561	                    display_name: ide
562	                        .metadata
563	                        .as_ref()
564	                        .map(|metadata| metadata.name.clone())
565	                        .unwrap_or_default(),
566	                    files: Vec::new(),
567	                    skipped: Some(
568	                        "never launched - recorded its factory defaults; start it once for it to \
569	                         take part"
570	                            .to_string(),
571	                    ),
572	                });
573	                continue;
574	            }
575	            let discovered = roamable::discover(ide, &self.sync_config, &manifest)?;
576	            let mut relatives: BTreeSet<String> = discovered.keys().cloned().collect();
577	            relatives.extend(staging.files_under(&self.store_root().join(SHARED)));
578	
579	            let product_defaults = self.defaults_for(ide, staging)?;
580	            let target = FileTarget {
581	                ide,
582	                discovered: &discovered,
583	                options,
584	                stamp: &stamp,
585	                defaults: product_defaults.as_ref(),
586	            };
587	            let mut files = Vec::new();
588	            for relative in relatives {
589	                let report = self.reconcile_file(&target, &relative, staging)?;
590	                if let Some(report) = report {
591	                    files.push(report);
592	                }
593	            }
594	            reports.push(IdeReport {
595	                directory: directory_name(ide),
596	                display_name: ide
597	                    .metadata
598	                    .as_ref()
599	                    .map(|metadata| metadata.name.clone())
600	                    .unwrap_or_default(),
601	                files,
602	                skipped: None,
603	            });
604	        }
605	        Ok(reports)
606	    }
