608	    /// Records a never-launched IDE's factory defaults into the store.
609	    ///
610	    /// This is the only moment the defaults are observable: once the IDE runs,
611	    /// its files mix defaults with whatever the user then changed.
612	    fn capture_defaults(
613	        &self,
614	        ide: &Ide,
615	        manifest: &[String],
616	        staging: &mut Staging,
617	    ) -> Result<()> {
618	        let path = self
619	            .store_root()
620	            .join(defaults::relative_path(&ide.product));
621	        let mut recorded = match staging.read(&path) {
622	            Some(raw) => defaults::ProductDefaults::parse(
623	                &String::from_utf8(raw)
624	                    .map_err(|_| JbsyncError::configuration("defaults file is not valid UTF-8"))?,
625	            )?,
626	            None => defaults::ProductDefaults::new(&ide.product, build_of(ide)),
627	        };
628	
629	        let mut changed = false;
630	        for (relative, source) in roamable::discover(ide, &self.sync_config, manifest)? {
631	            let Ok(raw) = std::fs::read(&source) else {
632	                continue;
633	            };
634	            let Ok(text) = String::from_utf8(raw) else {
635	                continue;
636	            };
637	            let Ok(document) = dom::parse(&text) else {
638	                continue;
639	            };
640	            changed |=
641	                recorded.record(&relative, project::project(&document).into_iter().collect());
642	        }
643	        if changed {
644	            recorded.build = build_of(ide).to_string();
645	            staging.write(&path, Some(recorded.encode()?.as_bytes()))?;
646	        }
647	        Ok(())
648	    }
