650	    /// The factory defaults recorded for this IDE's product, if any.
651	    fn defaults_for(
652	        &self,
653	        ide: &Ide,
654	        staging: &Staging,
655	    ) -> Result<Option<defaults::ProductDefaults>> {
656	        let path = self
657	            .store_root()
658	            .join(defaults::relative_path(&ide.product));
659	        let Some(raw) = staging.read(&path) else {
660	            return Ok(None);
661	        };
662	        let text = String::from_utf8(raw)
663	            .map_err(|_| JbsyncError::configuration("defaults file is not valid UTF-8"))?;
664	        Ok(Some(defaults::ProductDefaults::parse(&text)?))
665	    }
