667	    /// The allowlist other machines have already contributed to the store.
668	    fn remembered_manifest(&self, staging: &Staging) -> Result<Vec<String>> {
669	        let path = self.store_root().join(manifest::FILE_NAME);
670	        let Some(raw) = staging.read(&path) else {
671	            return Ok(Vec::new());
672	        };
673	        let text = String::from_utf8(raw)
674	            .map_err(|_| JbsyncError::configuration("manifest.toml is not valid UTF-8"))?;
675	        Ok(toml::from_str::<manifest::StoredManifest>(&text)
676	            .map_err(|error| JbsyncError::configuration(format!("manifest.toml: {error}")))?
677	            .roamable)
678	    }
