680	    /// Publishes what this machine's IDEs can prove about roamability, so a
681	    /// machine that never ran Backup and Sync inherits it.
682	    fn remember_manifest(&self, ides: &[&Ide], staging: &mut Staging) -> Result<()> {
683	        let path = self.store_root().join(manifest::FILE_NAME);
684	        let mut stored = match staging.read(&path) {
685	            Some(raw) => {
686	                let text = String::from_utf8(raw)
687	                    .map_err(|_| JbsyncError::configuration("manifest.toml is not valid UTF-8"))?;
688	                toml::from_str(&text).map_err(|error| {
689	                    JbsyncError::configuration(format!("manifest.toml: {error}"))
690	                })?
691	            }
692	            None => manifest::StoredManifest::default(),
693	        };
694	        if stored.absorb(&roamable::observed_manifest(ides)) {
695	            staging.write(&path, Some(stored.encode()?.as_bytes()))?;
696	        }
697	        Ok(())
698	    }
