700	    fn reconcile_file(
701	        &self,
702	        target: &FileTarget<'_>,
703	        relative: &str,
704	        staging: &mut Staging,
705	    ) -> Result<Option<FileReport>> {
706	        let FileTarget {
707	            ide,
708	            discovered,
709	            options,
710	            stamp,
711	            defaults,
712	        } = *target;
713	        let ide_file = discovered.get(relative).cloned().unwrap_or_else(|| {
714	            ide.path.join(roamable::target_relative_path(
715	                relative,
716	                ide,
717	                &self.sync_config,
718	            ))
719	        });
720	        // Through staging, not the filesystem: a dry run buffers the writes it
721	        // would make to this IDE, and later passes must see them. Reading the
722	        // disk directly would leave the IDE looking frozen while the store
723	        // moved on, so a second pass would conclude the IDE had deleted files.
724	        let raw = staging.read(&ide_file);
725	        let (local_view, removed) = raw.as_ref().map_or((None, Vec::new()), |bytes| {
726	            self.store_view(relative, bytes, defaults)
727	        });
728	
729	        // The file is present but holds nothing worth sharing — every setting in
730	        // it was pruned as a default. That is "no opinion", not "deleted", and
731	        // conflating the two makes two IDEs fight: one keeps contributing the
732	        // file and the other keeps withdrawing it. Contribute nothing and leave
733	        // both sides alone.
734	        if raw.is_some() && local_view.is_none() {
735	            return Ok(None);
736	        }
737	
738	        let store_file = self.shared_path(relative);
739	        let store = staging.read(&store_file);
740	        let base_file = self.base_path(ide, relative);
741	        let base = staging.read(&base_file);
742	
743	        // No special case for first contact. With no base, any setting the IDE
744	        // does not define is taken from the store, so a newly installed IDE
745	        // still adopts everything; only a setting both sides define differently
746	        // is a conflict, and there the default of keeping the local value means
747	        // a sync never silently discards what an IDE already had.
748	        let merged = merge::merge_file(
749	            base.as_deref(),
750	            local_view.as_deref(),
751	            store.as_deref(),
752	            options.policy,
753	        );
754	
755	        // Record what this IDE and the store agreed on even when nothing
756	        // changed. Without that snapshot the next divergence has no common
757	        // ancestor, so a setting only one side later edits looks like a
758	        // conflict rather than a plain update.
759	        if base.as_deref() != merged.content.as_deref() {
760	            staging.write(&base_file, merged.content.as_deref())?;
761	        }
762	
763	        if merged.is_noop() && removed.is_empty() {
764	            return Ok(None);
765	        }
766	
767	        staging.write(&store_file, merged.content.as_deref())?;
768	        if !options.collect_only {
769	            self.write_back(
770	                &WriteBack {
771	                    ide,
772	                    relative,
773	                    ide_file: &ide_file,
774	                    raw: raw.as_deref(),
775	                    merged: &merged,
776	                    stamp,
777	                },
778	                staging,
779	            )?;
780	        }
781	
782	        Ok(Some(FileReport {
783	            path: relative.to_string(),
784	            incoming: merged.incoming,
785	            outgoing: merged.outgoing,
786	            conflicts: merged.conflicts,
787	            pruned: removed,
788	        }))
789	    }
790	
791	    /// Applies the incoming settings to the IDE's own file.
792	    ///
793	    /// For XML this edits individual leaves rather than overwriting, so
794	    /// everything pruning removed from the store view — registry keys the IDE
795	    /// owns, tutorial progress, migration flags — survives untouched.
796	    fn write_back(&self, target: &WriteBack<'_>, staging: &mut Staging) -> Result<()> {
797	        let WriteBack {
798	            ide,
799	            relative,
800	            ide_file,
801	            raw,
802	            merged,
803	            stamp,
804	        } = *target;
805	        if merged.incoming.is_empty() {
806	            return Ok(());
807	        }
808	        let Some(content) = &merged.content else {
809	            // The setting file went away everywhere; leave the IDE's copy alone
810	            // rather than deleting a file we may not fully own.
811	            return Ok(());
812	        };
813	
814	        let updated = match (
815	            raw.and_then(|bytes| std::str::from_utf8(bytes).ok()),
816	            std::str::from_utf8(content).ok(),
817	        ) {
818	            (Some(raw_text), Some(merged_text)) => {
819	                match (dom::parse(raw_text), dom::parse(merged_text)) {
820	                    (Ok(mut target), Ok(donor)) => {
821	                        for change in &merged.incoming {
822	                            if change.path.is_empty() {
823	                                continue;
824	                            }
825	                            match &change.to {
826	                                Some(value) => {
827	                                    project::set_leaf(&mut target, &donor, &change.path, value);
828	                                }
829	                                None => project::remove_leaf(&mut target, &change.path),
830	                            }
831	                        }
832	                        dom::serialize(&target).into_bytes()
833	                    }
834	                    _ => content.clone(),
835	                }
836	            }
837	            // No local file yet, or not XML: take the merged content as-is.
838	            _ => content.clone(),
839	        };
840	
841	        if raw == Some(updated.as_slice()) {
842	            return Ok(());
843	        }
844	        if self.sync_config.jetbrains.backups && raw.is_some() {
845	            let backup = self
846	                .paths
847	                .backups_dir()
848	                .join(stamp)
849	                .join(directory_name(ide))
850	                .join(relative);
851	            staging.write(&backup, raw)?;
852	        }
853	        staging.write(ide_file, Some(&updated))
854	    }
855	}
