873	/// Folds a later reconciliation pass into the running report, so each IDE and
874	/// file is listed once with everything that happened to it.
875	fn absorb(accumulated: &mut Vec<IdeReport>, pass: Vec<IdeReport>) {
876	    for incoming in pass {
877	        let Some(existing) = accumulated
878	            .iter_mut()
879	            .find(|candidate| candidate.directory == incoming.directory)
880	        else {
881	            accumulated.push(incoming);
882	            continue;
883	        };
884	        for file in incoming.files {
885	            match existing
886	                .files
887	                .iter_mut()
888	                .find(|candidate| candidate.path == file.path)
889	            {
890	                Some(target) => {
891	                    target.incoming.extend(file.incoming);
892	                    target.outgoing.extend(file.outgoing);
893	                    target.conflicts.extend(file.conflicts);
894	                    // Every pass prunes the same settings, so keep the first
895	                    // pass's list rather than repeating it.
896	                    if target.pruned.is_empty() {
897	                        target.pruned = file.pruned;
898	                    }
899	                }
900	                None => existing.files.push(file),
901	            }
902	        }
903	        existing
904	            .files
905	            .sort_by(|left, right| left.path.cmp(&right.path));
906	    }
907	}
