938	/// Buffers writes so a dry run can still be truthful.
939	///
940	/// A sync reconciles the IDEs one after another, so the second IDE must see
941	/// what the first contributed. During a dry run nothing reaches disk, and
942	/// without this buffer every IDE would report the store as empty and claim to
943	/// be adding files that an earlier IDE had already supplied.
944	#[derive(Default)]
945	struct Staging {
946	    dry_run: bool,
947	    pending: std::collections::BTreeMap<PathBuf, Option<Vec<u8>>>,
948	}
949	
950	impl Staging {
951	    fn new(dry_run: bool) -> Self {
952	        Self {
953	            dry_run,
954	            pending: std::collections::BTreeMap::new(),
955	        }
956	    }
957	
958	    fn read(&self, path: &Path) -> Option<Vec<u8>> {
959	        if let Some(buffered) = self.pending.get(path) {
960	            return buffered.clone();
961	        }
962	        std::fs::read(path).ok()
963	    }
964	
965	    fn write(&mut self, path: &Path, content: Option<&[u8]>) -> Result<()> {
966	        if self.dry_run {
967	            self.pending
968	                .insert(path.to_path_buf(), content.map(<[u8]>::to_vec));
969	            return Ok(());
970	        }
971	        write_or_remove(path, content)
972	    }
973	
974	    /// Paths beneath `root` that exist once buffered writes are taken into
975	    /// account.
976	    fn files_under(&self, root: &Path) -> Vec<String> {
977	        let mut found: BTreeSet<String> = walk(root, root).into_iter().collect();
978	        for (path, content) in &self.pending {
979	            let Ok(relative) = path.strip_prefix(root) else {
980	                continue;
981	            };
982	            let relative = relative
983	                .components()
984	                .map(|part| part.as_os_str().to_string_lossy())
985	                .collect::<Vec<_>>()
986	                .join("/");
987	            if content.is_some() {
988	                found.insert(relative);
989	            } else {
990	                found.remove(&relative);
