                "[repo]\nremote = {:?}\n\n[jetbrains]\nroot = {:?}\n",
                remote.to_string_lossy(),
                jetbrains_root.to_string_lossy()
            ),
        )
        .unwrap();
        Self {
            _home: home,
            config_dir,
            jetbrains_root,
        }
    }

